  function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}

  /* ---------- نقاط الضعف: بتتحفظ على جهاز الطالب ---------- */
  const KEY="agri_mt_stats";
  function loadStats(){try{return JSON.parse(localStorage.getItem(KEY)||"{}")}catch(e){return {}}}
  function saveStats(st){try{localStorage.setItem(KEY,JSON.stringify(st))}catch(e){}}
  function qk(q){return q.id||("a"+q.n)}
  function updateStats(s){
    const st=loadStats();
    s.list.forEach((q,i)=>{
      const ok=s.picks[i]===q.a;
      const x=st[qk(q)]||{r:0,w:0,last:null};
      if(ok)x.r++;else x.w++;
      x.last=ok;
      st[qk(q)]=x;
    });
    saveStats(st);
  }
  // نقطة ضعف = سؤال آخر إجابة عليه كانت غلط
  function weakQs(){const st=loadStats();return DATA.qs.concat(PLANT.qs,CHEM.qs,MATH.qs).filter(q=>st[qk(q)]&&st[qk(q)].last===false)}

